function registerBuffer(te, he) {
  let pe = webAudioCtx.createBuffer(he.ch.length, he.ch[0].length, he.sr);
  for (let ye = 0; ye < he.ch.length; ye++) pe.getChannelData(ye).set(he.ch[ye]);
  buffers.set(te, pe), bufferCount++;
  let ge = waiters.get(te);
  if (ge) {
    waiters.delete(te);
    for (let ye of ge) try {
      ye(pe);
    } catch (Le) {
      console.error('[audio] ready callback', Le);
    }
  }
  return pe;
}

function makeTarget(O, q) {
  let U = new THREE.WebGLRenderTarget(O, O, {
    depthBuffer: !1,
    generateMipmaps: !0,
    minFilter: THREE.LinearMipmapLinearFilter,
    magFilter: THREE.LinearFilter,
    wrapS: THREE.RepeatWrapping,
    wrapT: THREE.RepeatWrapping,
    anisotropy: anisotropy,
    colorSpace: q ? THREE.SRGBColorSpace : THREE.NoColorSpace
  });
  return stats.bytes += O * O * 4 * 1.34, U;
}

/**
 * 定步长积分弹簧到目标值（最多 8ms 一子步，防大 dt 爆炸），返回当前位置
 * @module-ref src/core/math.js
 */
function stepSpring(spring, target, dt) {
  let n = dt > 0.012 ? Math.ceil(dt / 0.008) : 1,
    s = dt / n;
  for (let o = 0; o < n; o++) spring.v += ((target - spring.x) * spring.k - spring.v * spring.c) * s, spring.x += spring.v * s;
  return spring.x;
}
